package com.company.platform.inventory.application;
import com.company.platform.inventory.domain.Warehouse;import com.company.platform.inventory.infrastructure.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class WarehouseService{private final JdbcWarehouseStore store;private final TenantContextProvider tenant;public WarehouseService(JdbcWarehouseStore s,TenantContextProvider t){store=s;tenant=t;}public Warehouse create(String code,String name){return store.save(Warehouse.create(tenant.currentTenantId(),code,name));}public Warehouse get(UUID id){return store.find(tenant.currentTenantId(),id).orElseThrow(()->new NoSuchElementException("warehouse not found"));}public List<Warehouse> list(){return store.findAll(tenant.currentTenantId());}public Warehouse update(UUID id,String code,String name){Warehouse old=get(id);return store.save(new Warehouse(old.id(),old.tenantId(),code,name,old.active(),old.createdAt()));}}
